package uk.edbetter.kemdaily.core.chemistry

/**
 * Version 2 expansion of the offline reference library. Entries with identical compositions are
 * intentionally retained so formula lookup can report structural ambiguity instead of guessing.
 */
object ExpandedSubstanceCatalog {
    private fun e(
        id: String,
        name: String,
        formula: String,
        category: SubstanceCategory,
        fact: String,
        tier: Int = 2,
        aliases: List<String> = emptyList(),
    ) = substance(id, name, formula, category, fact, tier, aliases = aliases)

    val all: List<Substance> = listOf(
